package app.layan.test;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import app.layan.quran.*;import java.io.*;import org.json.*;

/** Real Android PdfRenderer, original pager and XZ decoding; corpus fixtures are exact pinned downloads. */
public final class QiraatRegression extends Instrumentation {
 private int assertions;private void check(boolean v,String message){assertions++;if(!v)throw new AssertionError(message);}
 public void onCreate(Bundle b){super.onCreate(b);start();}private void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
 private void install(String id)throws Exception{JSONObject m=QiraatData.metadata(getTargetContext(),id);String url=m.getString("url");File compressed=new File("/data/local/tmp/qiraat-corpus",url.substring(url.lastIndexOf('/')+1));check(QiraatDownload.sha(compressed).equals(m.getString("downloadSha256")),"Exact source archive "+id);File dir=QiraatData.directory(getTargetContext());dir.mkdirs();QiraatDownload.install(compressed,dir,id,m.getLong("bytes"),m.getString("sha256"),(p,s)->{});check(QiraatData.downloaded(getTargetContext(),id),"Downloaded status "+id);android.util.Log.i("LayanQiraatTest","Installed "+id);}
 private void await(QiraatReaderActivity r)throws Exception{boolean[] ready={false};for(int i=0;i<240;i++){ui(()->ready[0]=r.currentPageReady());if(ready[0])return;SystemClock.sleep(250);}throw new AssertionError("Reader did not render "+r.currentPage());}
 private QiraatReaderActivity launch(String id,int page)throws Exception{QiraatReaderActivity r=(QiraatReaderActivity)startActivitySync(new Intent(getTargetContext(),QiraatReaderActivity.class).putExtra("riwayah",id).putExtra("page",page).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(r);check(r.getSystemService(PowerManager.class).isInteractive(),"Phone is physically awake before reader swipe");getUiAutomation().adoptShellPermissionIdentity("android.permission.REORDER_TASKS");try{ui(()->r.getSystemService(ActivityManager.class).moveTaskToFront(r.getTaskId(),0));}finally{getUiAutomation().dropShellPermissionIdentity();}awaitFocus(r);return r;}
 private void awaitFocus(Activity a)throws Exception{boolean[] ready={false};for(int i=0;i<300;i++){ui(()->ready[0]=a.hasWindowFocus()&&a.getWindow().getDecorView().isShown());if(ready[0])return;SystemClock.sleep(100);}String[] state={""};ui(()->state[0]="focus="+a.hasWindowFocus()+" shown="+a.getWindow().getDecorView().isShown()+" finishing="+a.isFinishing()+" destroyed="+a.isDestroyed()+" task="+a.getTaskId());String diagnostics="";try(android.os.ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("dumpsys window windows");InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(fd);ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];for(int n;(n=in.read(buffer))!=-1;)bytes.write(buffer,0,n);diagnostics=bytes.toString("UTF-8");}throw new AssertionError("Reader window never gained actual input focus: "+state[0]+"\n"+diagnostics);}
 private void screen(Activity a,String name)throws Exception{SystemClock.sleep(500);Bitmap b=NativeScreens.capture(this,a);check(b!=null,"Screenshot "+name);File dir=a.getExternalFilesDir("tests");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 private void inject(MotionEvent event){try{event.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(event,true),"Real swipe input accepted");}finally{event.recycle();}}
 private void swipe(QiraatReaderActivity r,boolean right){check(r.hasWindowFocus(),"Reader has real input focus before swipe");View v=r.findViewById(QiraatReaderActivity.PAGER);int[] loc=new int[2];ui(()->v.getLocationOnScreen(loc));float y=loc[1]+v.getHeight()*.55f,start=loc[0]+v.getWidth()*(right?.1f:.9f),end=loc[0]+v.getWidth()*(right?.9f:.1f);long t=SystemClock.uptimeMillis();inject(MotionEvent.obtain(t,t,0,start,y,0));for(int i=1;i<=12;i++){SystemClock.sleep(40);inject(MotionEvent.obtain(t,SystemClock.uptimeMillis(),2,start+(end-start)*i/12f,y,0));}inject(MotionEvent.obtain(t,SystemClock.uptimeMillis(),1,end,y,0));SystemClock.sleep(2000);waitForIdleSync();}

 @Override public void onStart(){Bundle out=new Bundle();try{
  JSONObject c=QiraatData.catalog(getTargetContext());JSONArray all=c.getJSONArray("riwayat");check(c.getJSONArray("groups").length()==10,"Ten readers");check(all.length()==20,"Twenty riwayat");for(int i=0;i<10;i++)check(c.getJSONArray("groups").getJSONObject(i).getJSONArray("riwayat").length()==2,"Two riwayat");
  android.preference.PreferenceManager.getDefaultSharedPreferences(getTargetContext()).edit().putBoolean("useArabicNames",true).putBoolean("layanOriginalLanguageMigration092",true).putBoolean("nightMode",false).commit();
  File fixtureDirectory=QiraatData.directory(getTargetContext());File[] prior=fixtureDirectory.listFiles();if(prior!=null)for(File file:prior)check(file.isFile()&&file.delete(),"Reset this test device reading fixture "+file.getName());
  check(!QiraatData.downloaded(getTargetContext(),"ishaq"),"No bundled mushaf");install("ishaq");check(!QiraatData.downloaded(getTargetContext(),"idris"),"Independent downloads");
  Activity section=startActivitySync(new Intent(getTargetContext(),QiraatActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ListView list=section.findViewById(QiraatActivity.READINGS_LIST);check(list.getCount()==10,"Ten section rows");screen(section,"qiraat-section");ui(()->list.performItemClick(list.getAdapter().getView(9,null,list),9,9));check(list.getCount()==2,"Two independent download rows");screen(section,"qiraat-downloads");
  QiraatReaderActivity r=launch("ishaq",1);check(r.findViewById(QiraatReaderActivity.PAGER).getClass().getName().equals("androidx.viewpager.widget.NonRestoringViewPager"),"Original pager class");screen(r,"qiraat-ishaq-1");swipe(r,true);await(r);check(r.currentPage()==2,"RTL next swipe");swipe(r,false);await(r);check(r.currentPage()==1,"Previous swipe");ui(()->r.goToSurah(9));await(r);check(r.currentPage()==187,"Printed Tawbah index");ui(()->r.goToPage(300));await(r);screen(r,"qiraat-ishaq-300");ui(()->r.goToSurah(114));await(r);check(r.currentPage()==604,"Last surah");screen(r,"qiraat-ishaq-604");swipe(r,true);check(r.currentPage()==604,"Last page bound");ui(()->r.goToPage(300));await(r);ui(r::finish);
  QiraatReaderActivity resumed=(QiraatReaderActivity)startActivitySync(new Intent(getTargetContext(),QiraatReaderActivity.class).putExtra("riwayah","ishaq").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(resumed);check(resumed.currentPage()==300,"Per-riwayah offline resume");ui(resumed::finish);
  for(int i=0;i<all.length();i++){String id=all.getJSONObject(i).getString("id");if(!id.equals("ishaq"))install(id);try(QiraatData.Book b=new QiraatData.Book(getTargetContext(),id)){check(b.pageCount()==604,"604 printed pages "+id);check(b.starts.length==114&&b.starts[8]==187,"114 printed surahs "+id);check(b.surahAt(1)==1&&b.surahAt(187)==9,"Correct headings "+id);for(int p:new int[]{1,300,604}){Bitmap bitmap=b.render(p,400);int marks=0;for(int y=0;y<bitmap.getHeight();y+=2)for(int x=0;x<bitmap.getWidth();x+=2)if((bitmap.getPixel(x,y)>>>24)>0)marks++;check(marks>100,"Nonblank exact glyphs "+id+" "+p);bitmap.recycle();}}android.util.Log.i("LayanQiraatTest","Verified offline "+id);}
  android.preference.PreferenceManager.getDefaultSharedPreferences(getTargetContext()).edit().putBoolean("nightMode",true).commit();QiraatReaderActivity night=launch("warsh",3);screen(night,"qiraat-warsh-night");ui(night::finish);android.preference.PreferenceManager.getDefaultSharedPreferences(getTargetContext()).edit().putBoolean("nightMode",false).commit();
  ui(section::finish);check(QiraatData.downloaded(getTargetContext(),"ishaq")&&QiraatData.downloaded(getTargetContext(),"idris"),"Permanent independent files survive all twenty installs");check(getTargetContext().getPackageManager().getPackageInfo("app.layan.quran",0).versionName.equals("18.12"),"Requested version");out.putString("result","PASS "+assertions+" assertions: 20 independent installs; offline native PDF rendering; original RTL pager; complete pages; printed indexes; resume; day/night");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
}
